def compute_Last_Digit(a, b):
    # We need to find the last digit of (b! / a!) assuming a <= b and factorial(a) divides factorial(b).
    # Note that (b! / a!) = (a+1)*(a+2)*...*b

    # If a == b, the quotient is 1, last digit 1
    if a == b:
        return 1

    product = 1
    for x in range(a + 1, b + 1):
        product = (product * (x % 10)) % 10

        # Optimization: if product ends with 0, it will remain 0
        if product == 0:
            return 0

    return product

