def substract_elements(coll):
    if not isinstance(coll, (list, tuple)):
        # Base case: single number, no difference can be computed, return as is
        return coll

    # If collection has fewer than 2 elements, differences is empty collection of same type
    if len(coll) < 2:
        return type(coll)()

    # Compute differences recursively, preserving type
    result = []
    for i in range(len(coll) - 1):
        a, b = coll[i], coll[i + 1]
        if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
            # Both are nested collections, recurse
