        elif isinstance(a, (list, tuple)) or isinstance(b, (list, tuple)):
            # Mismatched types: treat missing elements as is and subtract if possible
            diff = substract_elements(pairwise_zip(
                a if isinstance(a, (list, tuple)) else (a,),
                b if isinstance(b, (list, tuple)) else (b,)
            ))
        else:
            # Both are numbers, subtract
            diff = b - a
        result.append(diff)

    # Return same type as input collection
    return type(coll)(result)

