def pairwise_subtract(a, b):
    # Returns a collection of pairwise differences a[i], b[i] -> b[i] - a[i]
    length = min(len(a), len(b))
    res = []
    for i in range(length):
        x, y = a[i], b[i]
        if isinstance(x, (list, tuple)) and isinstance(y, (list, tuple)):
            res.append(pairwise_subtract(x, y))
        elif isinstance(x, (list, tuple)) or isinstance(y, (list, tuple)):
            # Mismatch: treat the non-nested as a tuple
            if not isinstance(x, (list, tuple)):
                x = (x,)
            if not isinstance(y, (list, tuple)):
                y = (y,)
            res.append(pairwise_subtract(x, y))
        else:
            res.append(y - x)
    return type(a)(res)

