def find_solution(a: int, b: int, n: int):
    # We want non-negative integers x,y satisfying a*x + b*y = n.
    # If no such non-negative solution exists, return None.
    # If a or b is zero, handle separately.
    # Otherwise, try all possible x in [0, n//a] and check if y = (n - a*x)/b is non-negative integer.

    if a == 0 and b == 0:
        # Only if n == 0, x=y=0 works
        return (0, 0) if n == 0 else None
    if a == 0:
        # Then equation is b*y = n
        if b == 0:
            # Already handled above
            return None
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        # Then equation is a*x = n
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    max_x = n // a if a > 0 else 0
    if max_x < 0:
        # No x >= 0 can satisfy
        return None

    for x in range(max_x + 1):
        rem = n - a * x
        if rem < 0:
            break
        if rem % b == 0:
            y = rem // b
            if y >= 0:
                return (x, y)

    return None

