def dict_depth(d):
    if not isinstance(d, dict):
        return 0
    max_depth = 0
    for v in d.values():
        if isinstance(v, dict):
            depth = dict_depth(v)
            if depth > max_depth:
                max_depth = depth
        elif isinstance(v, (list, tuple)):
            # Check if any element inside list/tuple is a dict or contains dicts
            # The depth contributed by these is the max depth of any dict inside them
            def max_dict_depth_in_seq(seq):
                max_d = 0
                for item in seq:
                    if isinstance(item, dict):
                        d_depth = dict_depth(item)
                        if d_depth > max_d:
                            max_d = d_depth
                    elif isinstance(item, (list, tuple)):
                        inner_depth = max_dict_depth_in_seq(item)
                        if inner_depth > max_d:
                            max_d = inner_depth
                return max_d
            depth = max_dict_depth_in_seq(v)
            if depth > max_depth:
                max_depth = depth
    return 1 + max_depth

