def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Helper to check if all digits are 9
    if all(ch == '9' for ch in s):
        # Next palindrome greater than 999...9 is 100...001
        return int('1' + ('0' * (length - 1)) + '1')

    # Helper to create palindrome by mirroring left to right
    def make_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[-2::-1]
        else:
            return left + left[::-1]

    odd = (length % 2 != 0)
    mid = length // 2

    if odd:
        left = s[:mid+1]
    else:
        left = s[:mid]

    # Create palindrome by mirroring left half
    pal = int(make_palindrome(left, odd))

    if pal > num:
        return pal

    # Increment the middle part and mirror again
    # Convert left to int, increment, then convert back with proper zero padding
    left_num = int(left)
    left_num += 1
    left_inc = str(left_num)
    # If length changed due to increment (e.g. 99 -> 100)
    if len(left_inc) > len(left):
        # This happens when increment causes carry overflows like 999 -> 1000
        # For example, 999 -> next palindrome is 1001 (handled above),
        # but here if length increased, build palindrome accordingly
        return int('1' + ('0' * (length - 1)) + '1')
    else:
        pal = int(make_palindrome(left_inc, odd))
        return pal

