        return None
    left, right = 0, len(arr) - 1

    # If array is not rotated (sorted ascending)
    if arr[left] < arr[right]:
        return arr[right]

    while left <= right:
        mid = (left + right) // 2

        # Check if mid is maximum
        if mid < len(arr) - 1 and arr[mid] > arr[mid + 1]:
            return arr[mid]
        if mid > 0 and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]

        # Decide which half to search
        if arr[mid] >= arr[left]:
            # Max is in right half
            left = mid + 1
        else:
            # Max is in left half
            right = mid - 1
    return arr[0]

