def filter_data(students, min_height=None, max_height=None, min_width=None, max_width=None):
    """
    Filters students by their height and width.

    :param students: dict of {student_name: {'height': value, 'width': value}}
    :param min_height: minimum height inclusive filter (or None to ignore)
    :param max_height: maximum height inclusive filter (or None to ignore)
    :param min_width: minimum width inclusive filter (or None to ignore)
    :param max_width: maximum width inclusive filter (or None to ignore)
    :return: dict of filtered students with the same structure
    """
    def in_range(value, minv, maxv):
        if minv is not None and value < minv:
            return False
        if maxv is not None and value > maxv:
            return False
        return True

    filtered = {}
    for student, dims in students.items():
        h = dims.get('height')
        w = dims.get('width')
        if h is None or w is None:
            continue
        if in_range(h, min_height, max_height) and in_range(w, min_width, max_width):
            filtered[student] = dims
    return filtered

