def get_total_number_of_sequences(n: int, m: int) -> int:
    # dp[i][x] = number of sequences of length i ending with element x
    # Base case: for i=1, dp[1][x] = 1 for all 1 <= x <= m

    if n == 1:
        return m  # any element from 1 to m

    dp_prev = [1] * (m + 1)  # 1-based indexing, dp_prev[x] for i=1

    for length in range(2, n + 1):
        dp_curr = [0] * (m + 1)
        # To optimize, we can precompute prefix sums of dp_prev
        prefix_sum = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix_sum[x] = prefix_sum[x - 1] + dp_prev[x]
        prefix_sum[m + 1] = prefix_sum[m]

        for x in range(1, m + 1):
            # next element must be >= 2*x and <= m
            low = 2 * x
            if low > m:
                dp_curr[x] = 0
            else:
                # sum dp_prev[y] for y in [low, m]
                dp_curr[x] = prefix_sum[m] - prefix_sum[low - 1]
        dp_prev = dp_curr

    # sum over all possible last elements
    return sum(dp_prev[1:])

