def monotonic(l):
    if isinstance(l, list):
        # For list: duplicates allowed, no False return due to duplicates.
        # Return True if monotonic increasing or decreasing (non-strict, since duplicates allowed).
        # Return only boolean.
        if len(l) <= 1:
            return True
        def is_non_decreasing(i=0):
            if i == len(l) - 1:
